def transform(grid):
    h,w=len(grid),len(grid[0])
    out=[[0]*w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            if grid[r][c]==2: out[r][c]=2
    blocks=[(r,c) for r in range(h-1) for c in range(w-1)
            if grid[r][c]==2 and grid[r][c+1]==2 and grid[r+1][c]==2 and grid[r+1][c+1]==2]
    dirs={'TL':(-1,-1),'TR':(-1,1),'BR':(1,1),'BL':(1,-1)}
    for r,c in blocks:
        corner={'TL':(r-1,c-1),'TR':(r-1,c+2),'BL':(r+2,c-1),'BR':(r+2,c+2)}
        src={'TL':corner['BL'],'TR':corner['TL'],'BR':corner['TR'],'BL':corner['BR']}
        for pos,(dr,dc) in dirs.items():
            sr,sc=src[pos]; color=grid[sr][sc]
            rr,rc=corner[pos]
            while 0<=rr<h and 0<=rc<w:
                out[rr][rc]=color
                rr+=dr; rc+=dc
    return out

